    /* 只统计**真的画了**的刷新：REFR_START/REFR_READY 在无脏区时也会发
     * （见 lv_refr.c），这里用 RENDER_START 置位、REFR_READY 消费并清零，
     * 把空转的刷新节拍剔掉，refr 平均值才不被稀释。 */
    bool rendered;
} s_fps;
