static void helm_rot_cb(lv_timer_t * t)
{
    helm_page_id_t id;

    LV_UNUSED(t);
    if (s_sh.ui_covered || !s_sh.attached) {
        return;
    }

    id = helm_page_at(*helm_active_idx());
    if (id == HELM_PAGE_MAP || id == HELM_PAGE_TURN ||
        id == HELM_PAGE_CLIMB) {
        s_sh.rot_idx = (uint8_t)((s_sh.rot_idx + 1u) % 5u);
