{"content": "/**
 * @file bicycle_inval_probe.c
 * @brief 自行车 UI — inval_probe（WP-VERIFY2 临时插桩，测完回退）。
 */

#include "bicycle_inval_probe.h"

#include <nuttx/config.h>
#include <syslog.h>
#include <string.h>

#include "src/widgets/canvas/lv_canvas.h"
#include "src/widgets/label/lv_label.h"
#include "src/widgets/image/lv_image.h"

#define PROBE_TOP_N     8
#define PROBE_SIZE_N    6
#define PROBE_FLUSH_N   8
#define PROBE_TEXT_N    16

typedef struct {
    const lv_obj_t * obj;
    uint32_t n;
    uint32_t px;
    uintptr_t ra;
    int16_t x;
    int16_t y;
    int16_t w;
    int16_t h;
    int16_t px_;
    int16_t py_;
    int16_t pw;
    int16_t ph;
    uint8_t kind;            /* 0 label, 1 canvas, 2 obj, 3 widget */
    char text[PROBE_TEXT_N];
} probe_ent_t;

typedef struct {
    int16_t w;
    int16_t h;
    uint32_t n;
} probe_size_t;

typedef struct {
    int16_t x1, y1, x2, y2;
    uint32_t n;
} probe_flush_t;

static const char * s_tag;
static uint32_t s_win_start;
static uint32_t s_win_logged;

static uint32_t s_obj_inval_total;
static uint32_t s_area_inval_total;
static uint32_t s_refr_req_total;
static uint32_t s_refr_start_total;
static uint32_t s_flush_total;

/* 1 s 窗口 */
static uint32_t s_w_obj_n;
static uint32_t s_w_obj_px;
static uint32_t s_w_area_n;
static uint32_t s_w_area_px;
static uint32_t s_w_refr_req;
static uint32_t s_w_refr_start;
static uint32_t s_w_flush_n;
static uint32_t s_w_flush_px;
static uint32_t s_w_bucket[10];   /* <=8 <=16 <=24 <=32 <=48 <=64 <=128 <=256 >256 zero */
static probe_ent_t s_top[PROBE_TOP_N];
static probe_size_t s_sizes[PROBE_SIZE_N];
static probe_flush_t s_flush[PROBE_FLUSH_N];

static const char * inval_obj_kind(const lv_obj_t * obj)
{
    if (obj == NULL) {
        return "?";
    }
    if (lv_obj_check_type(obj, &lv_canvas_class)) {
        return "canvas";
    }
    if (lv_obj_check_type(obj, &lv_label_class)) {
        return "label";
    }
    if (lv_obj_check_type(obj, &lv_obj_class)) {
        return "obj";
    }
    return "widget";
}

static uint8_t inval_obj_kind_id(const lv_obj_t * obj)
{
    if (obj != NULL && lv_obj_check_type(obj, &lv_canvas_class)) {
        return 1;
    }
    if (obj != NULL && lv_obj_check_type(obj, &lv_label_class)) {
        return 0;
    }
    if (obj != NULL && lv_obj_check_type(obj, &lv_obj_class)) {
        return 2;
    }
    return 3;
}

static void inval_obj_text(const lv_obj_t * obj, char * out, size_t n)
{
    out[0] = '\0';
    if (obj == NULL) {
        return;
    }
    if (lv_obj_check_type(obj, &lv_label_class)) {
        const char * t = lv_label_get_text((lv_obj_t *)obj);
        if (t != NULL) {
            strncpy(out, t, n - 1);
            out[n - 1] = '\0';
        }
    } else if (lv_obj_check_type(obj, &lv_canvas_class)) {
        strncpy(out, "canvas", n - 1);
        out[n - 1] = '\0';
    }
}

static void inval_obj_record(const lv_obj_t * obj, const lv_area_t * area,
                             uintptr_t ra)
{
    int32_t w = area->x2 - area->x1 + 1;
    int32_t h = area->y2 - area->y1 + 1;
    uint32_t px = (w > 0 && h > 0) ? (uint32_t)w * (uint32_t)h : 0u;
    uint32_t side = (uint32_t)((w > h) ? w : h);
    int b;
    int i;
    int slot = -1;
    uint32_t min_n = 0xFFFFFFFFu;
    int min_i = 0;

    s_w_obj_n++;
    s_w_obj_px += px;

    if (w <= 0 || h <= 0) {
        b = 9;
    } else if (side <= 8) {
        b = 0;
    } else if (side <= 16) {
        b = 1;
    } else if (side <= 24) {
        b = 2;
    } else if (side <= 32) {
        b = 3;
    } else if (side <= 48) {
        b = 4;
    } else if (side <= 64) {
        b = 5;
    } else if (side <= 128) {
        b = 6;
    } else if (side <= 256) {
        b = 7;
    } else {
        b = 8;
    }
    s_w_bucket[b]++;

    /* 精确尺寸表 */
    for (i = 0; i < PROBE_SIZE_N; i++) {
        if (s_sizes[i].n != 0u && s_sizes[i].w == w && s_sizes[i].h == h) {
            s_sizes[i].n++;
            break;
        }
        if (s_sizes[i].n == 0u) {
            s_sizes[i].w = (int16_t)w;
            s_sizes[i].h = (int16_t)h;
            s_sizes[i].n = 1u;
            break;
        }
    }

    /* top-N 对象表 */
    for (i = 0; i < PROBE_TOP_N; i++) {
        if (s_top[i].obj == obj) {
            slot = i;
            break;
        }
        if (s_top[i].obj == NULL) {
            slot = i;
            break;
        }
        if (s_top[i].n < min_n) {
            min_n = s_top[i].n;
            min_i = i;
        }
    }
    if (slot < 0) {
        slot = min_i;
        memset(&s_top[slot], 0, sizeof(s_top[slot]));
    }

    {
        probe_ent_t * e = &s_top[slot];
        const lv_obj_t * parent = obj ? lv_obj_get_parent(obj) : NULL;

        if (e->n == 0u) {
            e->obj = obj;
            e->kind = inval_obj_kind_id(obj);
        }
        e->n++;
        e->px += px;
        e->ra = ra;
        e->x = (int16_t)area->x1;
        e->y = (int16_t)area->y1;
        e->w = (int16_t)w;
        e->h = (int16_t)h;
        if (parent != NULL) {
            e->px_ = (int16_t)parent->coords.x1;
            e->py_ = (int16_t)parent->coords.y1;
            e->pw = (int16_t)lv_area_get_width(&parent->coords);
            e->ph = (int16_t)lv_area_get_height(&parent->coords);
        } else {
            e->px_ = 0;
            e->py_ = 0;
            e->pw = 0;
            e->ph = 0;
        }
        inval_obj_text(obj, e->text, sizeof(e->text));
    }
}

static void inval_flush_record(const lv_area_t * area)
{
    int32_t w = area->x2 - area->x1 + 1;
    int32_t h = area->y2 - area->y1 + 1;
    uint32_t px = (w > 0 && h > 0) ? (uint32_t)w * (uint32_t)h : 0u;
    int i;
    int slot = -1;

    s_w_flush_n++;
    s_w_flush_px += px;

    for (i = 0; i < PROBE_FLUSH_N; i++) {
        if (s_flush[i].n != 0u && s_flush[i].x1 == area->x1 &&
            s_flush[i].y1 == area->y1 && s_flush[i].x2 == area->x2 &&
            s_flush[i].y2 == area->y2) {
            s_flush[i].n++;
            return;
        }
        if (s_flush[i].n == 0u && slot < 0) {
            slot = i;
        }
    }
    if (slot >= 0) {
        s_flush[slot].x1 = area->x1;
        s_flush[slot].y1 = area->y1;
        s_flush[slot].x2 = area->x2;
        s_flush[slot].y2 = area->y2;
        s_flush[slot].n = 1u;
    }
}

/**
 * @brief 对象级失效钩子（由 lv_obj_pos.c 的 lv_obj_invalidate_area 调用）。
 */
void bicycle_inval_probe_obj(const lv_obj_t * obj, const lv_area_t * area,
                             void * ra)
{
    s_obj_inval_total++;
    if (area == NULL) {
        return;
    }
    inval_obj_record(obj, area, (uintptr_t)ra);
}

/**
 * @brief 兼容旧符号：对象级失效探针。
