void bicycle_inval_probe_tag(const char * tag)
{
    s_tag = tag;
}

static void probe_window_reset(void)
{
    int i;

    s_w_obj_n = 0;
    s_w_obj_px = 0;
    s_w_area_n = 0;
    s_w_area_px = 0;
    s_w_refr_req = 0;
    s_w_refr_start = 0;
    s_w_flush_n = 0;
