}

static void probe_window_print(void)
{
    static const char * kind_name[4] = { "label", "canvas", "obj", "widget" };
    int i;

    syslog(LOG_WARNING,
        "[inval] S obj=%u objpx=%u darea=%u dareapx=%u refr_req=%u refr=%u flush=%u flushpx=%u "
        "b=%u,%u,%u,%u,%u,%u,%u,%u,%u,z=%u",
        (unsigned)s_w_obj_n, (unsigned)s_w_obj_px, (unsigned)s_w_area_n,
        (unsigned)s_w_area_px, (unsigned)s_w_refr_req,
        (unsigned)s_w_refr_start, (unsigned)s_w_flush_n,
        (unsigned)s_w_flush_px, (unsigned)s_w_bucket[0], (unsigned)s_w_bucket[1],
        (unsigned)s_w_bucket[2], (unsigned)s_w_bucket[3], (unsigned)s_w_bucket[4],
        (unsigned)s_w_bucket[5], (unsigned)s_w_bucket[6], (unsigned)s_w_bucket[7],
        (unsigned)s_w_bucket[8], (unsigned)s_w_bucket[9]);

    for (i = 0; i < PROBE_SIZE_N; i++) {
        if (s_sizes[i].n == 0u) {
            break;
        }
        syslog(LOG_WARNING, "[inval] Z %dx%d n=%u px=%u", (int)s_sizes[i].w,
            (int)s_sizes[i].h, (unsigned)s_sizes[i].n,
            (unsigned)((uint32_t)s_sizes[i].w * (uint32_t)s_sizes[i].h *
                       s_sizes[i].n));
    }

    for (i = 0; i < PROBE_TOP_N; i++) {
        probe_ent_t * e = &s_top[i];

        if (e->obj == NULL || e->n == 0u) {
            continue;
        }
        syslog(LOG_WARNING,
            "[inval] T i=%d n=%u px=%u area=%dx%d@%d,%d kind=%s txt=\"%s\" "
            "obj=%p parea=%dx%d@%d,%d ra=0x%08x",
            i, (unsigned)e->n, (unsigned)e->px, (int)e->w, (int)e->h,
            (int)e->x, (int)e->y, kind_name[e->kind & 3], e->text,
            (void *)e->obj, (int)e->pw, (int)e->ph, (int)e->px_, (int)e->py_,
            (unsigned)e->ra);
    }

    for (i = 0; i < PROBE_FLUSH_N; i++) {
        probe_flush_t * f = &s_flush[i];

        if (f->n == 0u) {
            continue;
        }
        syslog(LOG_WARNING, "[inval] F n=%u area=(%d,%d)-(%d,%d) %dx%d px=%u",
            (unsigned)f->n, (int)f->x1, (int)f->y1, (int)f->x2, (int)f->y2,
            (int)(f->x2 - f->x1 + 1), (int)(f->y2 - f->y1 + 1),
            (unsigned)((uint32_t)(f->x2 - f->x1 + 1) *
                       (uint32_t)(f->y2 - f->y1 + 1)));
    }

    probe_window_reset();
}

static void bicycle_inval_disp_event(lv_event_t * e)
{
    lv_event_code_t code = lv_event_get_code(e);

    switch (code) {
    case LV_EVENT_INVALIDATE_AREA: {
        lv_area_t * area = lv_event_get_invalidated_area(e);

        s_area_inval_total++;
        s_w_area_n++;
        if (area != NULL) {
            int32_t w = area->x2 - area->x1 + 1;
            int32_t h = area->y2 - area->y1 + 1;

            if (w > 0 && h > 0) {
                s_w_area_px += (uint32_t)w * (uint32_t)h;
            }
        }
        break;
    }
    case LV_EVENT_REFR_REQUEST:
        s_refr_req_total++;
        s_w_refr_req++;
        break;
    case LV_EVENT_REFR_START:
        s_refr_start_total++;
        s_w_refr_start++;
        break;
    case LV_EVENT_FLUSH_START: {
        lv_area_t * area = (lv_area_t *)lv_event_get_param(e);

        s_flush_total++;
        if (area != NULL) {
            inval_flush_record(area);
        }
        break;
    }
    default:
        break;
    }
}

static void bicycle_inval_summary_timer(lv_timer_t * tmr)
